module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
logic   [31:0]   count50   ;
    logic   [31:0]   count72   ;
    always_ff @(posedge clk50) begin
        if (count50 == COUNT_LIMIT) begin
            count50 <= 0;
        end else begin
            count50 <= count50 + 1;
        end
    end
    always_ff @(posedge clk72) begin
        if (count72 == COUNT_LIMIT) begin
            count72 <= 0;
        end else begin
            count72 <= count72 + 1;
        end
    end
    assign led[1] = count50[31];
    assign led[0] = count72[31];
    assign pmod[7:0] = count72[7:0];
endmodule

