        keypress_array[6] = 10'b0001000000;
        keypress_array[7] = 10'b0010000000;
        keypress_array[8] = 10'b0100000000;
        keypress_array[9] = 10'b1000000000;
    end
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            index <= 0;
            keypress <= 0;
        end else begin
            if (counter == 20) begin
                keypress <= keypress_array[index];
                counter <= 0;
                index <= index + 1;
                if (index == 10) begin
                    index <= 0;
                end
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

