module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] H_TOTAL=640;
parameter [31:0] H_SYNC=96;
parameter [31:0] H_BACK=48;
parameter [31:0] H_ACTIVE=480;
parameter [31:0] V_TOTAL=480;
parameter [31:0] V_SYNC=2;
parameter [31:0] V_BACK=33;
parameter [31:0] V_ACTIVE=288;
reg [9:0] h_counter = 0;
reg [9:0] v_counter = 0;
reg [9:0] h_sync = 0;
reg [9:0] h_back = 0;
reg [9:0] h_active = 0;
reg [9:0] v_sync = 0;
reg [9:0] v_back = 0;
reg [9:0] v_active = 0;
  always @(posedge pixel_clk) begin
    if((h_counter == (H_TOTAL - 1))) begin
      h_counter <= 0;
      if((v_counter == (V_TOTAL - 1))) begin
        v_counter <= 0;
      end
      else begin
        v_counter <= v_counter + 1;
      end
    end
    else begin
      h_counter <= h_counter + 1;
    end
  end
  assign hsync = (h_counter < h_sync) ? 1'b1 : 1'b0;
  assign vsync = (v_counter < v_sync) ? 1'b1 : 1'b0;
  assign pixel_x = h_counter;
  assign pixel_y = v_counter;
  assign visible_region = (h_counter < h_active) && (v_counter < v_active) ? 1'b1 : 1'b0;
endmodule

