module im2_control(
input wire i_CLK_CPU,
input wire i_reset,
input wire i_m1_n,
input wire i_mreq_n,
input wire i_iorq_n,
input wire [7:0] i_cpu_d,
output wire o_reti_decode,
output wire o_reti_seen
); 

parameter [31:0] S_0=0;
parameter [31:0] S_ED_T4=1;
parameter [31:0] S_4D_T4=2;
parameter [31:0] S_CB_T4=3;
reg [31:0] state = S_0;
reg ifetch_d;
reg [7:0] cpu_opcode;
wire ifetch;
wire ifetch_cancel;
  assign ifetch = i_m1_n & i_mreq_n & i_iorq_n;
  assign ifetch_cancel = i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n;
  always @(posedge i_CLK_CPU, posedge i_reset) begin
    if((i_reset == 1'b1)) begin
      state <= S_0;
    end else begin
      case(state)
      S_0 : begin
        if((ifetch == 1'b1)) begin
          state <= S_ED_T4;
        end
      end
      S_ED_T4 : begin
        if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
        else if((cpu_opcode == 8'hED)) begin
          state <= S_4D_T4;
        end
        else if((cpu_opcode == 8'hCB)) begin
          state <= S_CB_T4;
        end
      end
      S_4D_T4 : begin
        if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
        else if((cpu_opcode == 8'h4D)) begin
          state <= S_4D_T4;
        end
        else if((cpu_opcode == 8'hED)) begin
          state <= S_ED_T4;
        end
        else if((cpu_opcode == 8'hCB)) begin
          state <= S_CB_T4;
        end
      end
      S_CB_T4 : begin
        if((ifetch_cancel == 1'b1)) begin
          state <= S_0;
        end
        else if((cpu_opcode == 8'hCB)) begin
          state <= S_CB_T4;
        end
        else if((cpu_opcode == 8'hED)) begin
          state <= S_ED_T4;
        end
        else if((cpu_opcode == 8'h4D)) begin
          state <= S_4D_T4;
        end
      end
      default : begin
        state <= S_0;
      end
      endcase
    end
  end
  always @(state, i_cpu_d) begin
    case(state)
    S_0 : begin
      cpu_opcode <= 8'h00;
    end
    S_ED_T4 : begin
      cpu_opcode <= i_cpu_d;
    end
    S_4D_T4 : begin
      cpu_opcode <= i_cpu_d;
    end
    S_CB_T4 : begin
      cpu_opcode <= i_cpu_d;
    end
    default : begin
      cpu_opcode <= 8'h00;
    end
    endcase
  end
  assign ifetch_d = ifetch;
  assign o_reti_decode = (state == S_ED_T4) ? 1'b1 : 1'b0;
  assign o_reti_seen = (state == S_4D_T4) ? 1'b1 : 1'b0;
endmodule

