module spdr_uart_framer
(
    input clk_50,
    input rst,

    output reg tx_busy,
    input tx_vld,
    input [7:0] tx_data,

    output rx_vld,
    output [7:0] rx_data,
    output reg rx_frame_error,

    output uart_tx,
    input uart_rx
);
parameter SAMPLING_CLK_DIVIDER = 100000000 / 115200;

    reg [7:0] tx_shift_reg;
    reg [3:0] tx_counter;

    always @(posedge clk_50) begin
        if (rst) begin
            tx_busy <= 0;
            tx_shift_reg <= 0;
            tx_counter <= 0;
        end else begin
            if (tx_vld) begin
                tx_busy <= 1;
                tx_shift_reg <= {tx_data, tx_shift_reg[7:1]};
                tx_counter <= 0;
            end else if (tx_busy) begin
                tx_counter <= tx_counter + 1;
                if (tx_counter == 7) begin
                    tx_busy <= 0;
                end
            end
        end
    end

    wire [7:0] tx_serial = tx_shift_reg[0];

    assign uart_tx = tx_serial;

    reg [7:0] rx_shift_reg;
    reg [3:0] rx_counter;
    reg [3:0] rx_sample_counter;
    reg rx_sample_valid;

    always @(posedge clk_50) begin
        if (rst) begin
            rx_vld <= 0;
            rx_data <= 0;
            rx_frame_error <= 0;
            rx_shift_reg <= 0;
            rx_counter <= 0;
            rx_sample_counter <= 0;
            rx_sample_valid <= 0;
        end else begin
            if (rx_sample_valid) begin
                rx_sample_counter <= rx_sample_counter + 1;
                if (rx_sample_counter == SAMPLING_CLK_DIVIDER - 1) begin
                    rx_sample_counter <= 0;
                    rx_sample_valid <= 0;
                end
            end else begin
                if (rx_counter == 0) begin
                    rx_vld <= 0;
                    rx_data <= 0;
                    rx_frame_error <= 0;
                    rx_shift_reg <= 0;
                    rx_counter <= 0;
                end else begin
                    rx_shift_reg <= {rx_shift_reg[6:0], uart_rx};
                    rx_counter <= rx_counter - 1;
                    if (rx_counter == 0) begin
                        rx_vld <= 1;
                        rx_data <= rx_shift_reg;
                        rx_frame_error <= 0;
                    end else if (rx_counter == 1) begin
                        if (rx_shift_reg[7:1] != {7{rx_shift_reg[0]}}) begin
                            rx_frame_error <= 1;
                        end
                    end
                end
            end
        end
    end

    always @(posedge clk_50) begin
        if (rst) begin
            rx_sample_valid <= 0;
        end else begin
            if (rx_counter == 0) begin
                rx_sample_valid <= 0;
            end else if (rx_counter == 1) begin
                rx_sample_valid <= 1;
            end
        end
    end

endmodule

