module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load_p1;
wire         load_p2;
wire         load_p1_from_p2;
reg          s_ready_t;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = state[0];

assign load_p1 = state == ZERO ? s_valid :
                 state == ONE  ? m_ready :
                 state == TWO  ? 1'b1 : 1'b0;

assign load_p2 = state == ZERO ? 1'b0 :
                 state == ONE  ? s_valid :
                 state == TWO  ? m_ready :
                 1'b0;

assign load_p1_from_p2 = state == TWO ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
    end
end

always @(posedge clk) begin
    if (load_p2) begin
        data_p2 <= s_data;
    end
end

always @(posedge clk) begin
    if (load_p1_from_p2) begin
        data_p1 <= data_p2;
    end
end

always @(posedge clk) begin
    if (reset) begin
        s_ready_t <= 1'b0;
    end else begin
        s_ready_t <= state == ONE && next == TWO ? 1'b1 :
                     state == TWO && next == ONE ? 1'b0 :
                     s_ready_t;
    end
end

always @(posedge clk) begin
    if (reset) begin
        state <= ZERO;
    end else begin
        state <= next;
    end
end

always @(state, s_valid, m_ready, m_ready) begin
    case (state)
        ZERO: if (s_valid) next <= ONE;
        ONE : if (m_ready) next <= TWO;
        TWO : if (m_ready) next <= ONE;
        default: next <= ZERO;
    endcase
end

endmodule

