module shift_16_9 (
    input [15:0] x,
    input [15:0] y,
    input [1:0] shiftAlufn,
    output reg [15:0] shiftOut
  );
reg [15:0] temp;
  always @* begin
    case (shiftAlufn)
      2'b00: temp = x << y[3:0];
      2'b01: temp = x >> y[3:0];
