module reg_map (
    input               i_clk,
    input               i_rst_n,
    input       [15:0]  i_addr,
    input       [15:0]  i_wdata,
    input               i_wen,
    output  reg [15:0]  o_q,
    output  reg [15:0]  o_reg0000,
    output  reg [15:0]  o_reg0002,
    output  reg [15:0]  o_reg0004,
    output  reg [15:0]  o_reg0006
    );
localparam [15:0] ADDR0000 = 16'h0000;
    localparam [15:0] ADDR0002 = 16'h0002;
    localparam [15:0] ADDR0004 = 16'h0004;
    localparam [15:0] ADDR0006 = 16'h0006;

    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            o_reg0000 <= 16'h0000;
            o_reg0002 <= 16'h0000;
            o_reg0004 <= 16'h0000;
            o_reg0006 <= 16'h0000;
        end else begin
            if (i_wen) begin
                case (i_addr)
                    ADDR0000: o_reg0000 <= i_wdata;
                    ADDR0002: o_reg0002 <= i_wdata;
                    ADDR0004: o_reg0004 <= i_wdata;
                    ADDR0006: o_reg0006 <= i_wdata;
                endcase
            end
        end
    end

    always @(o_reg0000, o_reg0002, o_reg0004, o_reg0006) begin
        case (i_addr)
            ADDR0000: o_q <= o_reg0000;
            ADDR0002: o_q <= o_reg0002;
            ADDR0004: o_q <= o_reg0004;
            ADDR0006: o_q <= o_reg0006;
        endcase
    end

endmodule

