module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
    reg [AW-1:0] cached_addr0;
    reg [AW-1:0] cached_addr1;
    reg [DW-1:0] cached_data0;
    reg [DW-1:0] cached_data1;
    reg [AW-1:0] subaddr;
    reg good;
    always @ (addr or addr_ok or din or din_ok or we or addr_req or cached_addr0 or cached_addr1 or cached_data0 or cached_data1 or subaddr or good)
    begin
        if (addr_ok)
        begin
            if (DW == 8)
                addr_req = {addr[AW-1:2], 2'b00};
            else if (DW == 16)
                addr_req = {addr[AW-1:4], 4'b0000};
            else if (DW == 32)
                addr_req = {addr[AW-1:6], 6'b000000};
        end
        if (we && din_ok)
        begin
            if (DW == 8)
                cached_data0 = din[7:0];
            else if (DW == 16)
                cached_data0 = din[15:0];
            else if (DW == 32)
                cached_data0 = din[31:0];
            cached_addr0 = addr_req;
            good = 1;
        end
        else if (good)
        begin
            if (DW == 8)
                cached_data1 = cached_data0;
            else if (DW == 16)
                cached_data1 = cached_data0;
            else if (DW == 32)
                cached_data1 = cached_data0;
            cached_addr1 = cached_addr0;
            good = 0;
        end
        if (addr_req == cached_addr0)
            hit0 = 1;
        else
            hit0 = 0;
        if (addr_req == cached_addr1)
            hit1 = 1;
        else
            hit1 = 0;
        if (hit0 || hit1)
            req = 0;
        else
            req = 1;
        if (hit0)
            subaddr = 0;
        else if (hit1)
            subaddr = 1;
        else
            subaddr = 2;
        if (subaddr == 0)
            dout = cached_data0;
        else if (subaddr == 1)
            dout = cached_data1;
        else
            dout = din;
        if (we)
            data_ok = 1;
        else
            data_ok = 0;
        sdram_addr = addr_req + offset;
    end
endmodule

