module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [2:0] data;
reg [2:0] next_data;
reg [2:0] control;
reg [2:0] next_control;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      data <= {3{1'b0}};
    end else begin
      data <= next_data;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      control <= {3{1'b0}};
    end else begin
      control <= next_control;
    end
  end
  always @(data, control, D, A, WR, RD, CLK, RST) begin
    next_data <= data;
    next_control <= control;
    if((RD == 1'b1)) begin
      next_data <= {3{1'b0}};
    end
    if((WR == 1'b1)) begin
      next_data <= D;
    end
    if((A == 3'b001)) begin
      next_control <= {2{1'b0}};
    end
    if((A == 3'b010)) begin
      next_control <= {2{1'b1}};
    end
  end
  always @(data) begin
    case(data)
    3'b000 : begin
      Y <= 7'b0000001;
    end
    3'b001 : begin
      Y <= 7'b0000010;
    end
    3'b010 : begin
      Y <= 7'b0000100;
    end
    3'b011 : begin
      Y <= 7'b0001000;
    end
    3'b100 : begin
      Y <= 7'b0010000;
    end
    3'b101 : begin
      Y <= 7'b0100000;
    end
    3'b110 : begin
      Y <= 7'b1000000;
    end
    3'b111 : begin
      Y <= 7'b0000000;
    end
    default : begin
      Y <= 7'b0000000;
    end
    endcase
  end
  assign WCTRL = control[0];
endmodule

