module io_ps2_keyboard(
input wire clk,
input wire kbd_clk,
input wire kbd_dat,
output reg interrupt,
output reg [7:0] scanCode
); 

parameter CLK_SPEED = 100000000;
parameter timeout_const = CLK_SPEED / 1000000;
parameter debounce_const = CLK_SPEED / 1000000;
reg [7:0] shift_reg = 8'b00000000;
reg clk_filter = 1'b0;
reg [31:0] timeout = 0;
reg [31:0] bitsCount = 0;
  always @(posedge clk) begin
    if((bitsCount == 0)) begin
      shift_reg <= 8'b00000000;
      clk_filter <= 1'b0;
      timeout <= 0;
    end
    else if((bitsCount < 8)) begin
      if((clk_filter == 1'b0)) begin
        shift_reg <= {shift_reg[6:0],kbd_dat};
        clk_filter <= 1'b1;
        timeout <= timeout_const;
      end
      else if((timeout > 0)) begin
        timeout <= timeout - 1;
      end
      else begin
        clk_filter <= 1'b0;
      end
    end
    else begin
      if((clk_filter == 1'b0)) begin
        clk_filter <= 1'b1;
        timeout <= timeout_const;
      end
      else if((timeout > 0)) begin
        timeout <= timeout - 1;
      end
      else begin
        clk_filter <= 1'b0;
        bitsCount <= bitsCount + 1;
        if((bitsCount == 8)) begin
          interrupt <= 1'b1;
          scanCode <= shift_reg;
          bitsCount <= 0;
        end
      end
    end
  end
endmodule

