module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load_p1;
wire         load_p2;
wire         load_p1_from_p2;
reg          s_ready_t;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = state[0];

assign load_p1 = (state == ZERO && s_valid) ||
                 (state == ONE && s_valid && m_ready) ||
                 (state == TWO && m_ready);
assign load_p2 = (state == ONE && s_valid) ||
                 (state == TWO && s_valid && m_ready);
assign load_p1_from_p2 = (state == TWO);

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
    end
end

always @(posedge clk) begin
    if (load_p1_from_p2) begin
        data_p1 <= data_p2;
    end
end

always @(posedge clk) begin
    if (load_p2) begin
        data_p2 <= s_data;
    end
end

always @(posedge clk) begin
    if (reset) begin
        s_ready_t <= 1'b0;
        state     <= ZERO;
    end else begin
        s_ready_t <= next[0];
        state     <= next;
    end
end

always @(*) begin
    case (state)
        ZERO: if (s_valid && m_ready) next = ONE;
              else next = ZERO;
        ONE : if (~s_valid && m_ready) next = ONE;
              else if (s_valid && ~m_ready) next = TWO;
              else next = ONE;
        TWO : if (m_ready) next = ZERO;
              else next = TWO;
        default: next = ZERO;
    endcase
end

always @(*) begin
    case (state)
        ZERO: if (s_valid && m_ready) begin
                  load_p1_from_p2 = 1'b0;
              end
              else begin
                  load_p1_from_p2 = 1'b0;
              end
        ONE : if (s_valid && m_ready) begin
                  load_p1_from_p2 = 1'b0;
              end
              else if (~s_valid && m_ready) begin
                  load_p1_from_p2 = 1'b0;
              end
              else if (s_valid && ~m_ready) begin
                  load_p1_from_p2 = 1'b1;
              end
              else begin
                  load_p1_from_p2 = 1'b0;
              end
        TWO : if (m_ready) begin
                  load_p1_from_p2 = 1'b0;
              end
              else begin
                  load_p1_from_p2 = 1'b0;
              end
        default: load_p1_from_p2 = 1'b0;
    endcase
end

endmodule

