  parameter ACCUM_WIDTH  = 32,
  parameter OUT_WIDTH    = 32)
(
  input clk,
  input reset,
  input clear,
  input sample_in_stb,
  input signed [IN_WIDTH-1:0] sample_in_a,       
  input signed [IN_WIDTH-1:0] sample_in_b,       
  output signed [IN_WIDTH-1:0] sample_forward,   
  input signed [COEFF_WIDTH-1:0] coeff_in,       
  output signed [COEFF_WIDTH-1:0] coeff_forward, 
  input coeff_load_stb,                          
  input signed [ACCUM_WIDTH-1:0] sample_accum,   
  output signed [OUT_WIDTH-1:0] sample_out       
);
reg signed [IN_WIDTH-1:0] a_reg;
  reg signed [IN_WIDTH-1:0] b_reg;
  reg signed [IN_WIDTH-1:0] ad_reg;
  reg signed [COEFF_WIDTH-1:0] m_reg;
  reg signed [ACCUM_WIDTH-1:0] p_reg;

  always @(posedge clk) begin
    if (reset) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end else if (clear) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end else if (sample_in_stb) begin
      a_reg <= sample_in_a;
      b_reg <= sample_in_b;
      ad_reg <= a_reg + b_reg;
      m_reg <= coeff_in * ad_reg;
      p_reg <= sample_accum + m_reg;
    end else if (coeff_load_stb) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= coeff_in;
      p_reg <= sample_accum + m_reg;
    end
  end

  assign sample_forward = a_reg;
  assign coeff_forward = coeff_in;
  assign sample_out = p_reg[OUT_WIDTH-1:0];

endmodule

