module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);
wire do_enq; 
  wire do_deq; 
  wire [3:0] _T_11; 
  wire [1:0] _T_12; 
  reg  [3:0] _T_13; 
  reg  [1:0] _T_14; 
  reg  maybe_full; 
  assign io_enq_ready = ~maybe_full; 
  assign do_enq = io_enq_valid & io_enq_ready; 
  assign do_deq = io_deq_valid & io_deq_ready; 
  assign _T_11 = io_enq_bits_tl_state_size; 
  assign _T_12 = io_enq_bits_tl_state_source; 
  assign io_deq_valid = do_deq; 
  assign io_deq_bits_tl_state_size = _T_11; 
  assign io_deq_bits_tl_state_source = _T_12; 
  always @(posedge clock) begin
    if (reset) begin
      _T_13 <= 4'h0;
    end else if (do_enq) begin
      _T_13 <= _T_11;
    end else if (do_deq) begin
      _T_13 <= _T_11;
    end
  end
  always @(posedge clock) begin
    if (reset) begin
      _T_14 <= 2'h0;
    end else if (do_enq) begin
      _T_14 <= _T_12;
    end else if (do_deq) begin
      _T_14 <= _T_12;
    end
  end
  always @(posedge clock) begin
    if (reset) begin
      maybe_full <= 1'h0;
    end else if (do_enq) begin
      maybe_full <= 1'h0;
    end else if (do_deq) begin
      maybe_full <= 1'h0;
    end
  end
endmodule

