module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load_p1;
wire         load_p2;
wire         load_p1_from_p2;
reg          s_ready_t;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = (state == ONE);

assign load_p1 = s_valid & s_ready;
assign load_p2 = m_valid & m_ready;
assign load_p1_from_p2 = load_p1 & (state == ONE);

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
    end else if (load_p1_from_p2) begin
        data_p1 <= data_p2;
    end
end

always @(posedge clk) begin
    if (load_p2) begin
        data_p2 <= data_p1;
    end
end

always @(posedge clk) begin
    if (~reset) begin
        s_ready_t <= 1'b0;
    end else begin
        s_ready_t <= next == ONE ? load_p1 : s_ready_t;
    end
end

always @(posedge clk) begin
    if (~reset) begin
        state <= ZERO;
    end else begin
        state <= next;
    end
end

always @(*) begin
    case (state)
        ZERO: if (load_p1) next = ONE;
        ONE : if (~load_p1 & load_p2) next = TWO;
        TWO : if (load_p1_from_p2) next = ONE;
        default: next = ZERO;
    endcase
end

endmodule

