module bcd(
input wire clk,
input wire clr,
input wire ce,
output wire [3:0] q
); 

reg [3:0] dint;
reg [3:0] qreg;
  always @(posedge clk, posedge clr) begin
    if((clr == 1'b1)) begin
      qreg <= 4'b0000;
    end else begin
      if((ce == 1'b1)) begin
        qreg <= dint;
      end
    end
  end
  always @(posedge clk) begin
    if((clk == 1'b1)) begin
      if((dint == 4'b1001)) begin
        dint <= 4'b0000;
      end
      else begin
        dint <= dint + 1;
      end
    end
  end
  assign q = qreg;
endmodule

