        $readmemh("./minimal_modelb_rom_set/rom2.dat", rom2);
    end

    always @(posedge clk) begin
        case(addr[17:14])
            4'h0: data <= rom0[addr[13:0]];
            4'h1: data <= rom1[addr[13:0]];
            4'h2: data <= rom2[addr[13:0]];
            default: data <= 0;
