module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 100000000;
  parameter UART_BPS = 115200;
  parameter BPS_CNT = CLK_FREQ / UART_BPS;
  parameter UART_START = 1;
  parameter UART_DATA = 2;
  parameter UART_STOP = 3;
  parameter UART_IDLE = 4;
  reg [1:0] tx_flag;
  reg [7:0] tx_data;
  reg [31:0] clk_cnt;
  reg [3:0] tx_cnt;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      tx_flag <= UART_IDLE;
      tx_data <= 0;
      clk_cnt <= 0;
      tx_cnt <= 0;
      uart_txd <= 1;
    end else begin
      if (uart_en) begin
        tx_flag <= UART_START;
        tx_data <= uart_din;
        clk_cnt <= 0;
        tx_cnt <= 0;
      end else begin
        if (tx_flag == UART_START) begin
          if (clk_cnt == BPS_CNT) begin
            clk_cnt <= 0;
            tx_cnt <= 0;
            tx_flag <= UART_DATA;
          end else begin
            clk_cnt <= clk_cnt + 1;
          end
        end else if (tx_flag == UART_DATA) begin
          if (clk_cnt == BPS_CNT) begin
            clk_cnt <= 0;
            if (tx_cnt == 7) begin
              tx_flag <= UART_STOP;
            end else begin
              tx_cnt <= tx_cnt + 1;
            end
          end else begin
            clk_cnt <= clk_cnt + 1;
          end
        end else if (tx_flag == UART_STOP) begin
          if (clk_cnt == BPS_CNT) begin
            clk_cnt <= 0;
            if (tx_cnt == 7) begin
              tx_flag <= UART_IDLE;
              tx_cnt <= 0;
              uart_txd <= 1;
            end else begin
              tx_cnt <= tx_cnt + 1;
            end
          end else begin
            clk_cnt <= clk_cnt + 1;
          end
        end
      end
    end
  end
endmodule

