module boardSynchroniser(
    input clk,
	 input synch_en,
    input toggle_en,
    input [1:0] cnt_n,
    input [1:0] cnt_m,
    input opMode,
    output reg synchroStatus = 1'b0,
    inout syncInOut
    );
reg synch = 1'b0;
    reg [1:0] cnt = 2'b0;
    always @(posedge clk) begin
        if (toggle_en) begin
            if (cnt == cnt_n) begin
                synch <= 1'b0;
                cnt <= cnt_m;
            end else if (cnt == cnt_m) begin
                synch <= 1'b1;
                cnt <= cnt_n;
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
        if (opMode) begin
            synchroStatus <= synch;
            syncInOut <= synchroStatus;
        end else begin
            synchroStatus <= synchroStatus;
            syncInOut <= synchroStatus;
        end
    end
endmodule

