module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
wire [16:0] tmp;
    always @(*) begin
        tmp = {{3{data_i[13]}}, data_i} << shift_i;
    end
    always @(*) begin
        case (shift_i)
            2'b00: data_o = tmp;
            2'b01: data_o = tmp << 1;
            2'b10: data_o = tmp << 2;
            2'b11: data_o = tmp << 3;
        endcase
    end
endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @ (a or enable)
    begin
        if (enable == 0)
            y = 8'b00000000;
        else
            case (a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
    end
endmodule

module Data_Memory(input clk, rst, MemWrite, MemRead, mem_to_reg,
input [31:0] addr, write_data, output [31:0] read_data);
reg [31:0] data_mem [31:0];
    initial begin
        for (int i = 0; i < 32; i = i + 1) begin
            data_mem[i] = 0;
        end
    end
    always @(posedge clk) begin
        if (MemWrite) begin
            data_mem[addr] <= write_data;
        end
    end
    assign read_data = MemRead ? data_mem[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    generate
        genvar i;
        for (i = 0; i < BITS; i = i + 1) begin : gen
            assign enable_wires[i] = ena;
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    cnt[i] <= 0;
                end else if (enable_wires[i]) begin
                    if (updown) begin
                        cnt[i] <= cnt[i] + 1;
                    end else begin
                        cnt[i] <= cnt[i] - 1;
                    end
                end
            end
        end
    endgenerate
    assign out = cnt;
    assign ovf = (cnt == 0 && updown) || (cnt == (2 ** BITS - 1) && !updown);
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] r;
		assign b = r[3:0];
		assign s = r[7:4];
		assign g = r[11:8];
		assign q = r[15:12];
		always @ (binary)
		begin
			r = 0;
			repeat (16)
			begin
				r = r << 4;
				if (binary[3:0] > 4)
					r = r + 3;
				r = r + binary[3:0];
				binary = binary >> 4;
			end
			r = r >> 4;
		end
endmodule

