end
endmodule

module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg [DATA_BITS-1:0] mem [0:DEPTH-1];
reg                 empty;
reg                 full;
reg  [DEPTH_BITS-1:0] index;

assign empty_n = ~empty;
assign full_n  = ~full;
assign dout    = mem[index];

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        empty <= 1'b1;
        full  <= 1'b0;
        index <= {DEPTH_BITS{1'b0}};
    end
    else begin
        if (write && ~full) begin
            mem[index] <= din;
            if (index == DEPTH-1) begin
                empty <= 1'b0;
            end
            else begin
                index <= index + 1'b1;
            end
        end
        else if (read && ~empty) begin
            if (index == 0) begin
                full  <= 1'b1;
            end
            else begin
                index <= index - 1'b1;
            end
            empty <= 1'b1;
        end
    end
end

endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;
reg pre;
always @(posedge clk) begin
    if(timer == 1000000) begin
        if(btn_input == pre) begin
            btn_output <= btn_input;
            timer <= 0;
            pre <= btn_input;
        end
    end
    else begin
        timer <= timer + 1;
    end
end
endmodule

