module edge_detector (
    input wire clk,          
    input wire rst_n,        
    input wire signal_in,    
    output reg rising_out,   
    output reg falling_out   
);
reg signal_in_prev;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rising_out <= 0;
            falling_out <= 0;
            signal_in_prev <= 0;
        end else begin
            if (signal_in_prev == 0 && signal_in == 1) begin
                rising_out <= 1;
            end else begin
                rising_out <= 0;
            end
            if (signal_in_prev == 1 && signal_in == 0) begin
                falling_out <= 1;
            end else begin
                falling_out <= 0;
            end
            signal_in_prev <= signal_in;
        end
    end

endmodule

