		3'b001: bin_out = 3'b001;
		3'b011: bin_out = 3'b010;
		3'b010: bin_out = 3'b011;
		3'b110: bin_out = 3'b100;
		3'b111: bin_out = 3'b101;
		3'b101: bin_out = 3'b110;
		3'b100: bin_out = 3'b111;
	endcase
end
endmodule

