    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg          load_p1;
reg          load_p2;
reg          load_p1_from_p2;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = (state == ONE) ? 1'b1 : 1'b0;
assign m_data  = data_p1;
assign m_valid = (state == ONE) ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (reset == 1'b1)
        state <= ZERO;
    else
        state <= next;
end

always @(*) begin
    next = state;
    case (state)
        ZERO : if (s_valid == 1'b1 && s_ready == 1'b1)
                    {load_p1, load_p2, load_p1_from_p2} = 3'b101;
        ONE  : if (m_ready == 1'b1)
                    next = ZERO;
        TWO  : if (s_valid == 1'b1 && s_ready == 1'b1)
                    next = ONE;
    endcase
end

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
        load_p1 <= 1'b0;
    end
    else if (load_p1_from_p2) begin
        data_p1 <= data_p2;
        load_p1_from_p2 <= 1'b0;
    end
end

always @(posedge clk) begin
    if (load_p2) begin
        data_p2 <= s_data;
        load_p2 <= 1'b0;
    end
end

endmodule

module Incer #(
