module udpAppMux_txLengthNetwork_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg [DEPTH_BITS-1:0] mem [DEPTH-1:0];
reg [DEPTH_BITS-1:0] index;

assign dout = mem[index];

assign empty_n = (index != 0);
assign full_n  = (index != DEPTH-1);

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        index <= 0;
    end else begin
        if (write) begin
            if (index == DEPTH-1) begin
                index <= index;
            end else begin
                index <= index + 1;
            end
        end else if (read) begin
            if (index == 0) begin
                index <= index;
            end else begin
                index <= index - 1;
            end
        end
    end
end

generate
    genvar i;
    for (i = 0; i < DEPTH; i = i + 1) begin : gen_mem
        always @(posedge clk or posedge aclr) begin
            if (aclr) begin
                mem[i] <= {DATA_BITS{1'b0}};
            end else begin
                if (write && (i == index)) begin
                    mem[i] <= din;
                end
            end
        end
    end
endgenerate

