module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);
localparam S_IDLE = 2'b00;
    localparam S_RUN  = 2'b01;
    localparam S_DONE = 2'b10;

    reg   [1:0] state, state_n;
    reg   [DWIDTH-1:0] cnt_val, cnt_val_n;
    reg   run, run_n;
    reg   done, done_n;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            cnt_val <= 0;
            run <= 0;
            done <= 0;
        end else begin
            state <= state_n;
            cnt_val <= cnt_val_n;
            run <= run_n;
            done <= done_n;
        end
    end

    always @(*) begin
        state_n = state;
        cnt_val_n = cnt_val;
        run_n = run;
        done_n = done;

        case (state)
            S_IDLE: begin
                if (start_i) begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val_i;
                end
            end
            S_RUN: begin
                if (cnt_val == cnt_i) begin
                    state_n = S_DONE;
                    run_n = 1;
                end else begin
                    run_n = 1;
                end
            end
            S_DONE: begin
                if (start_i) begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val_i;
                end else begin
                    state_n = S_IDLE;
                    done_n = 1;
                end
            end
        endcase
    end

    assign run_o = run;
    assign done_o = done;

endmodule

