(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,
    output reg          lfsr_out_f
);
localparam WIDTH = 16;
    localparam TAP1 = 16'h0001;
    localparam TAP2 = 16'h0002;
    localparam TAP3 = 16'h0004;
    localparam TAP4 = 16'h0008;
    localparam TAP5 = 16'h0010;
    localparam TAP6 = 16'h0020;
    localparam TAP7 = 16'h0040;
    localparam TAP8 = 16'h0080;
    localparam TAP9 = 16'h0100;
    localparam TAP10 = 16'h0200;
    localparam TAP11 = 16'h0400;
    localparam TAP12 = 16'h0800;
    localparam TAP13 = 16'h1000;
    localparam TAP14 = 16'h2000;
    localparam TAP15 = 16'h4000;
    localparam TAP16 = 16'h8000;

    reg [15:0] lfsr_state_n;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr_state_f <= 16'h0000;
        end else if (lfsr_ld) begin
            lfsr_state_f <= lfsr_seed;
        end else if (lfsr_step) begin
            lfsr_state_f <= lfsr_state_n;
        end
    end

    always @(*) begin
        lfsr_state_n = lfsr_state_f;
        lfsr_out_f = lfsr_state_f[WIDTH-1];
        lfsr_state_n[WIDTH-1] = lfsr_state_f[TAP1] ^ lfsr_state_f[TAP2] ^ lfsr_state_f[TAP3] ^ lfsr_state_f[TAP4] ^ lfsr_state_f[TAP5] ^ lfsr_state_f[TAP6] ^ lfsr_state_f[TAP7] ^ lfsr_state_f[TAP8] ^ lfsr_state_f[TAP9] ^ lfsr_state_f[TAP10] ^ lfsr_state_f[TAP11] ^ lfsr_state_f[TAP12] ^ lfsr_state_f[TAP13] ^ lfsr_state_f[TAP14] ^ lfsr_state_f[TAP15] ^ lfsr_state_f[TAP16];
    end

endmodule

