module FFlr(
input wire clk,
input wire [31:0] f,
output reg [31:0] g
); 

wire [7:0] len_raw;
wire [7:0] len;
wire [7:0] x_mask;
wire [31:0] f_masked;
wire [31:0] f_incr;
wire [31:0] f_out;
wire [31:0] res;
  assign len_raw = f[30:23] - 8'b11111111;
  assign len = len_raw > 8'b00000000 ? len_raw : 8'b00000000;
  assign x_mask = {8{1'b0}} | {1'b1, len_raw[6:0]};
  assign f_masked = f & {32{1'b1}} >> x_mask;
  assign f_incr = f_masked + 1;
  assign f_out = f[31:0] > 32'b00000000000000000000000000000000 ? f_incr : f_masked;
  assign res = {f[31], f_out[22:0]};
  reg [31:0] g_reg;
  reg [31:0] g_reg2;
  always @(posedge clk) begin
    g_reg <= res;
    g_reg2 <= g_reg;
  end
  assign g = g_reg2;
endmodule

