            end
            2'b01: begin
                o_Dataout = 8'b0;
                o_Addressdata = RY[2:0];
                ReadWrite = 1'b0;
            end
            2'b10: begin
                o_Dataout = Num[2:0];
                o_Addressdata = RX;
                ReadWrite = 1'b1;
            end
            2'b11: begin
                o_Dataout = RX;
                o_Addressdata = RY;
                ReadWrite = 1'b0;
            end
            default: begin
                o_Dataout = 8'b0;
                o_Addressdata = 8'b0;
                ReadWrite = 1'b0;
            end
        endcase
    end
endmodule

