module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg          load_p1;
reg          load_p2;
reg          load_p1_from_p2;
wire         s_ready_t;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = load_p1;

always @(posedge clk) begin
    if (reset == 1'b1)
        state <= ZERO;
    else
        state <= next;
end

always @(state, s_valid, m_ready) begin
    case (state)
        ZERO: if (s_valid == 1'b1)
            next <= ONE;
        ONE : if (m_ready == 1'b1)
            next <= TWO;
        TWO : if (s_valid == 1'b0)
            next <= ZERO;
        default: next <= ZERO;
    endcase
end

always @(state, s_data, s_valid, m_ready) begin
    load_p1_from_p2 = 1'b0;
    load_p1         = 1'b0;
    load_p2         = 1'b0;
    s_ready_t       = 1'b0;

    case (state)
        ZERO: begin
            s_ready_t = 1'b1;
        end
        ONE : begin
            s_ready_t = 1'b0;
            load_p1   = 1'b1;
            load_p2   = s_valid;
        end
        TWO : begin
            load_p1   = m_ready;
            load_p2   = 1'b0;
            load_p1_from_p2 = m_ready & s_valid;
        end
        default: begin
            s_ready_t = 1'b1;
        end
    endcase
end

always @(posedge clk) begin
    if (load_p1 == 1'b1)
        data_p1 <= s_data;
    else if (load_p1_from_p2 == 1'b1)
        data_p1 <= data_p2;
end

always @(posedge clk) begin
    if (load_p2 == 1'b1)
        data_p2 <= s_data;
end

endmodule

