module fsm_seq_10010_moore(
    input clk,
    input rst_n,
    input x,
    output z
    );
parameter S1 = 3'b000;
    parameter S2 = 3'b001;
    parameter S3 = 3'b010;
    parameter S4 = 3'b011;
    parameter S5 = 3'b100;
    parameter S6 = 3'b101;
    reg [2:0] state;
    reg [2:0] next;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S1;
        end else begin
            state <= next;
        end
    end
    always @(state or x) begin
        case (state)
            S1: begin
                if (x) begin
                    next = S2;
                end else begin
                    next = S1;
                end
            end
            S2: begin
                if (x) begin
                    next = S3;
                end else begin
                    next = S1;
                end
            end
            S3: begin
                if (x) begin
                    next = S4;
                end else begin
                    next = S1;
                end
            end
            S4: begin
                if (x) begin
                    next = S5;
                end else begin
                    next = S1;
                end
            end
            S5: begin
                if (x) begin
                    next = S6;
                end else begin
                    next = S1;
                end
            end
            S6: begin
                if (x) begin
                    next = S1;
                end else begin
                    next = S1;
                end
            end
            default: begin
                next = S1;
            end
        endcase
    end
    assign z = (state == S6) ? 1'b1 : 1'b0;
endmodule

