module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [DATA_WIDTH-1:0]mem[FIFO_DEPTH-1:0];
reg [clog2_FIFO_DEPTH:0]wrptr,rdptr;

wire wrreq_n = ~wrreq;
wire rdreq_n = ~rdreq;

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        wrptr <= 0;
        rdptr <= 0;
        usedw <= 0;
    end
    else
    begin
        if(wrreq_n && !full)
        begin
            mem[wrptr] <= data_in;
            wrptr <= (wrptr == FIFO_DEPTH-1) ? 0 : wrptr + 1;
        end
        if(rdreq_n && !empty)
        begin
            rdptr <= (rdptr == FIFO_DEPTH-1) ? 0 : rdptr + 1;
        end
    end
end

assign data_out = mem[rdptr];

assign empty = (usedw == 0);
assign full = (usedw == FIFO_DEPTH-1);

assign usedw = (wrptr >= rdptr) ? (wrptr - rdptr) : (FIFO_DEPTH - (rdptr - wrptr));

endmodule

