  reg [31:0] M_x, M_y, M_z, M_w;
  reg [31:0] M_x_q, M_y_q, M_z_q, M_w_q, M_w_d;

  always @(posedge clk) begin
    if (rst) begin
      M_x_q <= SEED;
      M_y_q <= SEED;
      M_z_q <= SEED;
      M_w_q <= SEED;
    end else begin
      M_x_q <= M_x;
      M_y_q <= M_y;
      M_z_q <= M_z;
      M_w_q <= M_w;
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      M_x <= SEED;
      M_y <= SEED;
      M_z <= SEED;
      M_w <= SEED;
    end else begin
      M_x <= M_y;
      M_y <= M_z;
      M_z <= M_w;
      M_w <= M_w_d;
    end
  end

  assign M_w_d = {1'b0, M_w_q[30:0]} ^ {M_x_q[30:0], M_y_q[30:0], M_z_q[30:0], M_w_q[30:0]};

  always @(posedge clk) begin
    if (next) begin
      M_w <= M_w_d;
      num <= M_w_q;
    end
  end

endmodule

