module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg [1:0] state;
reg [1:0] next_state;


always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= 2'b00;
	else
		state <= next_state;
end


always @(*)
begin
	case (state)
		2'b00: next_state = 2'b01;
		2'b01: next_state = 2'b10;
		2'b10: next_state = 2'b11;
		2'b11: next_state = 2'b00;
	endcase
end


always @(*)
begin
	case (state)
		2'b00: begin
					red = 1'b1;
					yellow = 1'b0;
					green = 1'b0;
				end
		2'b01: begin
					red = 1'b0;
					yellow = 1'b1;
					green = 1'b0;
				end
		2'b10: begin
					red = 1'b0;
					yellow = 1'b0;
					green = 1'b1;
				end
		2'b11: begin
					red = 1'b0;
					yellow = 1'b1;
					green = 1'b0;
				end
	endcase
end
endmodule

