module lpm_or (
    data,  
    result 
);


    input  [(lpm_size * lpm_width)-1:0] data;


    output [lpm_width-1:0] result;
parameter lpm_width = 1;
    parameter lpm_size = 1;

    reg [lpm_width-1:0] result_tmp;

    initial begin
        if (lpm_width <= 0) begin
            $display("lpm_width must be greater than 0");
            $finish;
        end
        if (lpm_size <= 0) begin
            $display("lpm_size must be greater than 0");
            $finish;
        end
    end

    always @(*) begin
        result_tmp = 1'b0;
        for (i = 0; i < lpm_size; i = i + 1) begin
            result_tmp = result_tmp | data[(i * lpm_width) +: lpm_width];
        end
        result = result_tmp;
    end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
parameter NUM_DIV = 6;
    reg [31:0] cnt;
    reg clk_div;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0;
            clk_div <= 0;
        end else begin
            if (cnt < (NUM_DIV/2)) begin
                cnt <= cnt + 1;
            end else begin
                cnt <= 0;
                clk_div <= ~clk_div;
            end
        end
    end
endmodule

