  logic [IdxWidth-1:0] idx;
  logic valid;
  logic error;
  always_comb begin
    valid = 1'b0;
    error = 1'b0;
    idx = '0;
    matched_rules = '0;
    for (int i = 0; i < NoRules; i++) begin
      if (addr_map_i[i].start_addr <= addr_i && addr_i <= addr_map_i[i].end_addr) begin
        matched_rules[i] = 1'b1;
        valid = 1'b1;
        idx = addr_map_i[i].idx;
      end
    end
    if (!valid && en_default_idx_i) begin
      valid = 1'b1;
      idx = default_idx_i;
    end
    if (!valid && !en_default_idx_i) begin
      error = 1'b1;
    end
  end
