module zsignals
(
  input wire clk,
  input wire zpos,
  input wire rst_n,
  input wire iorq_n,
  input wire mreq_n,
  input wire m1_n,
  input wire rfsh_n,
  input wire rd_n,
  input wire wr_n,
  output wire rst,
  output wire m1,
  output wire rfsh,
  output wire rd,
  output wire wr,
  output wire iorq,
  output wire mreq,
  output wire rdwr,
  output wire iord,
  output wire iowr,
  output wire iordwr,
  output wire memrd,
  output wire memwr,
  output wire memrw,
  output wire opfetch,
  output wire intack,
  output wire iorq_s,
  output wire mreq_s,
  output wire iord_s,
  output wire iowr_s,
  output wire iordwr_s,
  output wire memrd_s,
  output wire memwr_s,
  output wire memrw_s,
  output wire opfetch_s
);
reg iorq_r, mreq_r;
  reg iorq_s_r, mreq_s_r;
  reg iord_r, iowr_r, iordwr_r;
  reg memrd_r, memwr_r, memrw_r;
  reg opfetch_r, intack_r;
  always @(posedge clk) begin
    if (zpos) begin
      iorq_r <= iorq_n;
      mreq_r <= mreq_n;
    end
    iorq_s_r <= iorq_r;
    mreq_s_r <= mreq_r;
    iord_r <= iorq_r & mreq_r & m1_n;
    iowr_r <= iorq_r & mreq_r & ~m1_n;
