module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
parameter IDLE = 0, SETUP = 1, ACCESS = 2;
reg [1:0] state, next_state;
always @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end
always @(state, Transfer, PREADY, PSLVERR) begin
    case (state)
        IDLE: begin
            if (Transfer) begin
                next_state = SETUP;
            end else begin
                next_state = IDLE;
            end
        end
        SETUP: begin
            if (PREADY) begin
                next_state = ACCESS;
            end else begin
                next_state = SETUP;
            end
        end
        ACCESS: begin
            if (Transfer) begin
                if (Wr_Rd) begin
                    PSELx = 1;
                    PENABLE = 1;
                    PWRITE = 1;
                    PWDATA = write_data;
                    next_state = ACCESS;
                end else begin
                    PSELx = 1;
                    PENABLE = 1;
                    PWRITE = 0;
                    PADDR = Address;
                    next_state = ACCESS;
                end
            end else begin
                if (PSLVERR) begin
                    next_state = IDLE;
                end else begin
                    if (Wr_Rd) begin
                        read_data = PRDATA;
                        next_state = IDLE;
                    end else begin
                        next_state = IDLE;
                    end
                end
            end
        end
        default: begin
            next_state = IDLE;
        end
    endcase
end
endmodule

