module PulseCounter(
input wire clk,
output wire pulse
); 

parameter [31:0] upper_bound=1000000000;
reg [27:0] counter = 0;
  always @(posedge clk) begin
    if((counter == upper_bound)) begin
      counter <= 0;
    end
    else begin
      counter <= counter + 1;
    end
  end
  assign pulse = (counter == upper_bound) ? 1'b1 : 1'b0;
endmodule

