module uart_tx_tester ( input clk_50M, input run_test_raw, input tx_busy, output reg [7:0] data_out, output reg trigger );
parameter [1:0]
  LOAD_DATA = 2'b00,
  TRIGGER = 2'b01,
  POLL_BUSY = 2'b10,
  PAUSE = 2'b11;

  parameter MSG_DELAY = 100000000;

  reg [1:0] state, next_state;
  reg [3:0] data_pos, next_data_pos;
  reg [31:0] delay, next_delay;

  always @(posedge clk_50M) begin
    state <= next_state;
    data_pos <= next_data_pos;
    delay <= next_delay;
  end

  always @(*) begin
    next_state = state;
    next_data_pos = data_pos;
    next_delay = delay;

    case (state)
      LOAD_DATA: begin
        next_state = TRIGGER;
        next_data_pos = 0;
      end
      TRIGGER: begin
        next_state = POLL_BUSY;
        next_delay = MSG_DELAY;
      end
      POLL_BUSY: begin
        if (tx_busy) begin
          next_state = POLL_BUSY;
          next_delay = delay - 1;
        end else begin
          next_state = PAUSE;
          next_delay = MSG_DELAY;
        end
      end
      PAUSE: begin
        if (delay == 0) begin
          next_state = LOAD_DATA;
        end else begin
          next_state = PAUSE;
          next_delay = delay - 1;
        end
      end
      default: begin
        next_state = LOAD_DATA;
      end
    endcase

    case (state)
      LOAD_DATA: begin
        next_data_pos = 0;
      end
      TRIGGER: begin
        next_data_pos = 0;
      end
      POLL_BUSY: begin
        next_data_pos = 0;
      end
      PAUSE: begin
        next_data_pos = 0;
      end
      default: begin
        next_data_pos = 0;
      end
    endcase

    case (state)
      LOAD_DATA: begin
        next_delay = 0;
      end
      TRIGGER: begin
        next_delay = 0;
      end
      POLL_BUSY: begin
        next_delay = delay;
      end
      PAUSE: begin
        next_delay = delay;
      end
      default: begin
        next_delay = 0;
      end
    endcase
  end

  always @(posedge clk_50M) begin
    if (run_test_raw) begin
      case (state)
        LOAD_DATA: begin
          data_out <= 8'h20;
          trigger <= 1;
        end
        TRIGGER: begin
          data_out <= 8'h48;
          trigger <= 1;
        end
        POLL_BUSY: begin
          data_out <= 8'h65;
          trigger <= 1;
        end
        PAUSE: begin
          data_out <= 8'h20;
          trigger <= 1;
        end
        default: begin
          data_out <= 8'h00;
          trigger <= 0;
        end
      endcase
    end else begin
      data_out <= 8'h00;
      trigger <= 0;
    end
  end

  always @(posedge clk_50M) begin
    if (run_test_raw) begin
      case (state)
        LOAD_DATA: begin
          if (data_pos == 0) begin
            next_state = TRIGGER;
          end else begin
            next_state = LOAD_DATA;
          end
        end
        TRIGGER: begin
          if (data_pos == 0) begin
            next_state = POLL_BUSY;
          end else begin
            next_state = TRIGGER;
          end
        end
        POLL_BUSY: begin
          if (data_pos == 0) begin
            next_state = PAUSE;
          end else begin
            next_state = POLL_BUSY;
          end
        end
        PAUSE: begin
          if (data_pos == 0) begin
            next_state = LOAD_DATA;
          end else begin
            next_state = PAUSE;
          end
        end
        default: begin
          next_state = LOAD_DATA;
        end
      endcase
    end else begin
      next_state = LOAD_DATA;
    end
  end

endmodule

