output [1:0] addr_sel, load_sel, count_sel; 
output count_up, top_enable, alu_enable;    
output [5:0] alu_op;
reg [3:0] ustate; 
reg [21:0] ucode [0:255]; 
reg [3:0] nx_ustate; 
assign read = ucode[ustate][0]; 
assign write = ucode[ustate][1]; 
assign iack = ucode[ustate][2]; 
assign addr_sel = ucode[ustate][3:5]; 
assign load_sel = ucode[ustate][6:8]; 
assign count_sel = ucode[ustate][9:11]; 
assign count_up = ucode[ustate][12]; 
assign top_enable = ucode[ustate][13]; 
assign alu_enable = ucode[ustate][14]; 
assign alu_op = ucode[ustate][15:20]; 
always @(posedge clk) begin
    if (reset) begin
        ustate <= 4'b0000;
    end else begin
        ustate <= nx_ustate;
    end
end
always @(*) begin
    case (ustate)
        4'b0000: begin
            if (irq) begin
                nx_ustate = 4'b0001;
            end else begin
                nx_ustate = 4'b0010;
            end
        end
        4'b0001: begin
            nx_ustate = 4'b0000;
        end
        4'b0010: begin
            if (ir[7:6] == 2'b00) begin
                nx_ustate = 4'b0011;
            end else begin
                nx_ustate = 4'b0100;
            end
        end
        4'b0011: begin
            nx_ustate = 4'b0010;
        end
        4'b0100: begin
            if (ir[7:6] == 2'b00) begin
                nx_ustate = 4'b0101;
            end else begin
                nx_ustate = 4'b0110;
            end
        end
