            if (ir[7:6] == 2'b00) begin
                nx_ustate = 4'b1011;
            end else begin
                nx_ustate = 4'b1100;
            end
        end
        4'b1011: begin
            nx_ustate = 4'b1010;
        end
        4'b1100: begin
            if (ir[7:6] == 2'b00) begin
                nx_ustate = 4'b1101;
            end else begin
                nx_ustate = 4'b1110;
            end
        end
        4'b1101: begin
            nx_ustate = 4'b1100;
        end
        4'b1110: begin
            if (ir[7:6] == 2'b00) begin
                nx_ustate = 4'b1111;
            end else begin
                nx_ustate = 4'b0000;
            end
        end
        4'b1111: begin
