module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
	input startGameEn; 
	input [7:0]user_x; 
	input [6:0]user_y; 
	input [7:0]enemy_x; 
	input [6:0]enemy_y; 
	input [160*120-1:0] enem_grid; 
	output reg [7:0] x; 
	output reg [6:0] y; 
	output reg[2:0] colour;
reg clear;
	always @(posedge clk) begin
		if (startGameEn) begin
			x <= 0;
			y <= 0;
			clear <= 1;
		end
		else begin
			if (clear) begin
				colour <= 3'b000;
				clear <= 0;
			end
			else begin
				if (x == 160 && y == 120) begin
					x <= 0;
					y <= 0;
				end
				else begin
					if (x == user_x && y == user_y) begin
						colour <= 3'b001;
					end
					else if (x == enemy_x && y == enemy_y) begin
						colour <= 3'b010;
					end
					else if (enem_grid[(x*120)+y] == 1) begin
						colour <= 3'b100;
					end
					else begin
						colour <= 3'b000;
					end
					x <= x + 1;
					y <= y + 1;
				end
			end
		end
	end
endmodule

module Start_UP_Handler(
input wire i_CLK,
output wire o_RST
); 

parameter [31:0] g_Clock_Frequency=100000000;
parameter [31:0] g_Initial_Reset_Time=100000000;
parameter [31:0] c_Initial_Reset_Clocks = (g_Initial_Reset_Time / g_Clock_Frequency);
reg r_RST = 1'b1;
reg [31:0] r_RST_Counter = 0;
  always @(posedge i_CLK) begin
    if((r_RST == 1'b1)) begin
      r_RST_Counter <= 0;
      r_RST <= 1'b1;
    end
    else if((r_RST_Counter < c_Initial_Reset_Clocks)) begin
      r_RST_Counter <= r_RST_Counter + 1;
      r_RST <= 1'b1;
    end
    else begin
      r_RST <= 1'b0;
    end
  end
  assign o_RST = r_RST;
endmodule

module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);
reg [1:0] state = 2'b00;
reg [1:0] nextState = 2'b00;
reg [31:0] timeCount = 0;
reg [31:0] timeoutCounter = 0;
reg [31:0] timeout = 100000000;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 2'b00;
    end else begin
        state <= nextState;
    end
end
always @(state, do_measure) begin
    case (state)
        2'b00: begin
            nextState = do_measure ? 2'b01 : 2'b00;
        end
        2'b01: begin
            nextState = 2'b10;
        end
        2'b10: begin
            nextState = 2'b11;
        end
        2'b11: begin
            nextState = 2'b00;
        end
        default: begin
            nextState = 2'b00;
        end
    endcase
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sonar_trigger <= 0;
        READY <= 0;
        timeCount <= 0;
        timeoutCounter <= 0;
    end else begin
        case (state)
            2'b00: begin
                sonar_trigger <= 0;
                READY <= 0;
                timeCount <= 0;
                timeoutCounter <= 0;
            end
            2'b01: begin
                sonar_trigger <= 1;
                READY <= 0;
                timeCount <= 0;
                timeoutCounter <= 0;
            end
            2'b10: begin
                sonar_trigger <= 0;
                READY <= 0;
                timeCount <= 0;
                timeoutCounter <= 0;
            end
            2'b11: begin
                sonar_trigger <= 0;
                READY <= 1;
                timeCount <= 0;
                timeoutCounter <= 0;
            end
            default: begin
                sonar_trigger <= 0;
                READY <= 0;
                timeCount <= 0;
                timeoutCounter <= 0;
            end
        endcase
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        timeoutCounter <= 0;
    end else begin
        if (state == 2'b11) begin
            timeoutCounter <= timeoutCounter + 1;
        end else begin
            timeoutCounter <= 0;
        end
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        timeCount <= 0;
    end else begin
        if (state == 2'b11) begin
            if (sonar_pulse) begin
                timeCount <= timeCount + 1;
            end else begin
                timeCount <= 0;
            end
        end else begin
            timeCount <= 0;
        end
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        inches <= 0;
    end else begin
        if (state == 2'b11) begin
            if (timeCount < timeout) begin
                inches <= timeCount * 125000000 / 1000000000;
            end else begin
                inches <= 0;
            end
        end else begin
            inches <= 0;
        end
    end
end
endmodule

