    s_input_a_ack = 0;
  end

  always @(posedge clk)
  begin
    if (rst)
    begin
      state = 0;
      s_input_a_ack = 0;
    end
    else
    begin
      case (state)
      0:
      begin
        if (input_a_stb)
        begin
          value = input_a;
          state = 1;
        end
        else
        begin
          state = 0;
        end
      end
      1:
      begin
        $fopena("resp_z");
        $fdisplay("resp_z",value[63:32]);
        $fdisplay("resp_z",value[31:0]);
        $fclose("resp_z");
        state = 0;
        s_input_a_ack = 1;
      end
      endcase
    end
  end

  assign input_a_ack = s_input_a_ack;

endmodule

