reg sel_conf;

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        sel_sram <= 1'b0;
        sel_conf <= 1'b0;
    end else begin
        sel_sram <= cpu_data_addr[31:2] == CONF_ADDR_BASE[31:2] ? 1'b0 : 1'b1;
        sel_conf <= cpu_data_addr[31:2] == CONF_ADDR_BASE[31:2] ? 1'b1 : 1'b0;
