module timer_variable(
input wire zedboard_clk,
input wire enable,
input wire reset,
output reg timerOutput
); 

reg [31:0] timer_value = 0;
  always @(posedge zedboard_clk) begin
    if(reset == 1'b1) begin
      timer_value <= 0;
    end
    else if(timer_value == 100000) begin
      timerOutput <= 1'b1;
      timer_value <= 0;
    end
    else begin
      timerOutput <= 1'b0;
      timer_value <= timer_value + 1;
    end
  end
endmodule

module NAND3xp33_ASAP7_75t_R (Y, A, B, C);
output Y;
input A, B, C;
wire A__bar, B__bar, C__bar;

	not (C__bar, C);
	not (B__bar, B);
	not (A__bar, A);
	or (Y, A__bar, B__bar, C__bar);


	specify
		(A => Y) = 0;
		(B => Y) = 0;
		(C => Y) = 0;
	endspecify
endmodule

