module barrel_shifter_tb;
reg [7:0] in;
	reg [3:0] control;
	reg [7:0] expected;
	reg [7:0] out;
	reg [7:0] error;

	barrel_shifter uut (
		.in(in),
		.control(control),
		.out(out),
		.expected(expected)
	);

	initial begin
		error = 0;
		in = 128;
		control = 4;
		expected = 128;
		#10;
		if (out != expected) begin
			$display("FAIL: Shift by 4");
			error = 1;
		end
		in = 255;
		control = 2;
		expected = 128;
		#10;
		if (out != expected) begin
			$display("FAIL: Shift by 2");
			error = 1;
		end
		in = 128;
		control = 1;
		expected = 64;
		#10;
		if (out != expected) begin
			$display("FAIL: Shift by 1");
			error = 1;
		end
		in = 255;
		control = 7;
		expected = 128;
		#10;
		if (out != expected) begin
			$display("FAIL: Shift by 7");
			error = 1;
		end
		if (error == 0) begin
			$display("PASS");
		end
	end
endmodule

