module FIFO_icmp_server_dataStreams_V_keep_V_0 (
    clk,
    reset,
    if_empty_n,
    if_read_ce,
    if_read,
    if_dout,
    if_full_n,
    if_write_ce,
    if_write,
    if_din);

input clk;
input reset;
output if_empty_n;
input if_read_ce;
input if_read;
output[DATA_WIDTH - 1:0] if_dout;
output if_full_n;
input if_write_ce;
input if_write;
input[DATA_WIDTH - 1:0] if_din;
parameter MEM_STYLE = "shiftreg";
parameter DATA_WIDTH = 32'd1;
parameter ADDR_WIDTH = 32'd1;
parameter DEPTH = 32'd2;

wire[ADDR_WIDTH - 1:0] shiftReg_addr ;
wire[DATA_WIDTH - 1:0] shiftReg_data, shiftReg_q;
reg[ADDR_WIDTH:0] mOutPtr = {(ADDR_WIDTH+1){1'b1}};
reg if_full_n = 0, if_empty_n = 1;
reg[ADDR_WIDTH:0] mOutPtr_next = {(ADDR_WIDTH+1){1'b1}};
reg if_full_n_next = 0, if_empty_n_next = 0;

assign if_empty_n = if_full_n;
assign if_full_n = if_full_n_next;
assign if_dout = shiftReg_q;
assign shiftReg_data = if_din;

always @(posedge clk) begin
    if (reset == 1'b1)
    begin
        mOutPtr <= ~{ADDR_WIDTH+1{1'b0}};
        if_full_n <= 1'b0;
        if_empty_n <= 1'b1;
    end
    else begin
        mOutPtr <= mOutPtr_next;
        if_full_n <= if_full_n_next;
        if_empty_n <= if_empty_n_next;
    end
end

always @(mOutPtr or shiftReg_q or if_write or if_read) begin
    if_write_ce = if_write & if_full_n;
    if_read_ce = if_read & if_empty_n;

    if_full_n_next = 1'b1;
    if_empty_n_next = 1'b0;
    shiftReg_addr = mOutPtr[ADDR_WIDTH] == 1'b0 ? mOutPtr[ADDR_WIDTH-1:0] : {ADDR_WIDTH{1'b0}};
    mOutPtr_next = mOutPtr;

    if (if_write_ce == 1'b1)
    begin
        if_full_n_next = if_full_n;
        if_empty_n_next = 1'b0;
        mOutPtr_next = mOutPtr + {ADDR_WIDTH{1'b0}};
    end
    if (if_read_ce == 1'b1)
    begin
        if_full_n_next = 1'b0;
        if_empty_n_next = if_empty_n;
        mOutPtr_next = mOutPtr - {ADDR_WIDTH{1'b0}};
    end
end

