module SCK_control_slave( input wire SCK_in, input wire CPOL, input wire CPHA, input wire idle, output reg S_BaudRate, output wire Shift_clk, output wire Sample_clk );
reg Shift_clk_int, Sample_clk_int;
    always @(idle or S_BaudRate) begin
        if (idle == 1'b0 && S_BaudRate == 1'b1) begin
            Shift_clk_int <= 1'b1;
        end else begin
            Shift_clk_int <= 1'b0;
        end
    end
    always @(idle or S_BaudRate) begin
        if (idle == 1'b0 && S_BaudRate == 1'b0) begin
            Sample_clk_int <= 1'b1;
        end else begin
            Sample_clk_int <= 1'b0;
        end
    end
    assign Shift_clk = Shift_clk_int;
    assign Sample_clk = Sample_clk_int;
    always @(*) begin
        case({CPOL, CPHA})
            2'b00: S_BaudRate = 1'b0;
            2'b01: S_BaudRate = 1'b1;
            2'b10: S_BaudRate = 1'b0;
            2'b11: S_BaudRate = 1'b1;
        endcase
    end
endmodule

