module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30; 
parameter count = 4; 
reg [1:0]delay; 

top top1(clk,reset,rxD,s_in);

reg [7:0]s_in;

always@(posedge clk)
begin
    if(reset)
    begin
        counter <= 0;
        sout <= 0;
        signal <= 0;
    end
    else
    begin
        if(counter == count)
        begin
            delay <= 1;
            counter <= 0;
        end
        else
        begin
            delay <= 0;
            counter <= counter + 1;
        end
        if(delay == 1)
        begin
            signal <= 1;
        end
        else
        begin
            signal <= 0;
        end
        sout <= {sout[29:0],s_in[7]};
    end
end
endmodule

