module clock_divider(clock_in,clock_out
    );
input clock_in; 
output reg clock_out;
parameter DIVISOR = 100000000;
reg [27:0] counter = 0;
always @(posedge clock_in) begin
    counter <= counter + 1;
    if (counter < DIVISOR - 1) begin
        clock_out <= 1'b0;
    end else if (counter < DIVISOR) begin
        clock_out <= 1'b1;
    end else begin
        counter <= 0;
    end
end
endmodule

