   always @(posedge clk or posedge rst) begin
      if (rst) begin
	 counter <= 0;
      end else begin
	 counter <= counter + 1;
      end
   end
   always @(posedge clk or posedge rst) begin
      if (rst) begin
	 led <= 0;
      end else begin
	 if (counter[CTR_LEN-1:CTR_LEN-8] == 0) begin
	    led <= 8'b00000001;
