	    led <= 8'b00000010;
	 end else if (counter[CTR_LEN-1:CTR_LEN-8] == 2) begin
	    led <= 8'b00000100;
	 end else if (counter[CTR_LEN-1:CTR_LEN-8] == 3) begin
	    led <= 8'b00001000;
	 end else if (counter[CTR_LEN-1:CTR_LEN-8] == 4) begin
	    led <= 8'b00010000;
	 end else if (counter[CTR_LEN-1:CTR_LEN-8] == 5) begin
	    led <= 8'b00100000;
	 end else if (counter[CTR_LEN-1:CTR_LEN-8] == 6) begin
	    led <= 8'b01000000;
	 end else if (counter[CTR_LEN-1:CTR_LEN-8] == 7) begin
	    led <= 8'b10000000;
	 end else begin
	    led <= 8'b00000000;
	 end
      end
   end
