module lfsr #( parameter WIDTH = 10, parameter SEED = 10'h2aa, parameter TAPS = 10'h2C2 ) ( input wire clk_i, input wire rst_i, input wire next_i, output wire [WIDTH-1:0] output_o );
reg [WIDTH-1:0] lfsr_reg;
wire feedback;
assign feedback = lfsr_reg[TAPS] ^ lfsr_reg[TAPS>>1] ^ lfsr_reg[TAPS>>2] ^ lfsr_reg[TAPS>>3] ^ lfsr_reg[TAPS>>4];
always @(posedge clk_i) begin
    if (rst_i) begin
        lfsr_reg <= SEED;
    end else if (next_i) begin
        lfsr_reg <= {lfsr_reg[WIDTH-2:0], feedback};
    end
end
assign output_o = lfsr_reg;
endmodule

