output reg ringer,
output reg motor
); 

always @(ring, vibrate_mode) begin
    if((vibrate_mode == 1'b1)) begin
      motor <= 1'b1;
      ringer <= 1'b0;
    end
    else begin
      motor <= 1'b0;
      ringer <= 1'b1;
    end
  end
