module TopModule(
input wire mode,
input wire too_cold,
input wire too_hot,
input wire fan_on,
output reg heater,
output reg aircon,
output reg fan
); 

always @(mode, too_cold, too_hot, fan_on) begin
    heater <= 1'b0;
    aircon <= 1'b0;
    fan <= 1'b0;
    if((mode == 1'b1)) begin
      heater <= too_cold;
      fan <= fan_on;
    end
    else if((mode == 1'b0)) begin
      aircon <= too_hot;
      fan <= fan_on;
    end
  end
endmodule

