module TopModule(
    input  clk,
    input  aresetn,
    input  x,
    output z
    );
reg [1:0] state;
    reg [1:0] next_state;
    reg z;
    always @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            state <= 2'b00;
            z <= 1'b0;
        end else begin
            state <= next_state;
            z <= 1'b0;
        end
    end
    always @(*) begin
        case (state)
            2'b00: begin
                if (x) begin
                    next_state = 2'b01;
                end else begin
                    next_state = 2'b00;
                end
            end
            2'b01: begin
                if (x) begin
                    next_state = 2'b10;
                end else begin
                    next_state = 2'b00;
                end
            end
            2'b10: begin
                if (x) begin
                    next_state = 2'b11;
                end else begin
                    next_state = 2'b00;
                end
            end
            2'b11: begin
                if (x) begin
                    next_state = 2'b11;
                end else begin
                    next_state = 2'b00;
                end
            end
            default: begin
                next_state = 2'b00;
            end
        endcase
        if (state == 2'b11) begin
            z = 1'b1;
        end
    end
endmodule

