      end

  endmodule

module TopModule(
    input clk,
    input x,
    input [2:0] y,
    output Y0,
    output z
    );
reg [2:0] Y;
    always @(posedge clk) begin
        if (x == 0) begin
            Y <= {Y[2], Y[1], y[2:0]};
        end else begin
            Y <= {Y[2], Y[1], y[2:0]};
        end
    end
    assign Y0 = Y[0];
    assign z = Y[2];
endmodule

module TopModule(
input wire [2:0] y,
input wire w,
output wire Y1
); 

reg [2:0] y_next;
  always @(y, w) begin
    case(y)
    3'b000 : begin
      y_next <= 3'b001;
    end
    3'b001 : begin
      y_next <= 3'b000;
    end
    3'b010 : begin
      y_next <= 3'b011;
    end
    3'b011 : begin
      y_next <= 3'b100;
    end
    3'b100 : begin
      y_next <= 3'b101;
    end
    3'b101 : begin
      y_next <= 3'b010;
    end
    default : begin
      y_next <= 3'b000;
    end
    endcase
  end
  assign Y1 = y_next[1];
endmodule

