module TopModule(
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);
reg [1:0] state;
    reg f_reg;
    reg g_reg;
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin
                    state <= 2'b01;
                end
                2'b01: begin
                    f_reg <= 1'b1;
                    state <= 2'b10;
                end
                2'b10: begin
                    if (x == 1'b1 && y == 1'b0 && g_reg == 1'b1) begin
                        g_reg <= 1'b1;
                    end else if (x == 1'b0 && y == 1'b1 && g_reg == 1'b1) begin
                        g_reg <= 1'b1;
                    end else if (x == 1'b1 && y == 1'b1 && g_reg == 1'b1) begin
                        g_reg <= 1'b1;
                    end else if (x == 1'b0 && y == 1'b0 && g_reg == 1'b1) begin
                        g_reg <= 1'b0;
                    end else begin
                        g_reg <= 1'b0;
                    end
                    state <= 2'b00;
                end
            endcase
        end
    end
    assign f = f_reg;
    assign g = g_reg;
endmodule

