module TopModule(
    input  clk,
    input  resetn,
    input  r,
    output g
    );
reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] g;
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= 3'b000;
        end else begin
            state <= next_state;
        end
    end
    always @(state, r) begin
        case (state)
            3'b000: begin
                if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state <= 3'b000;
                end else if (r[0] == 1'b1 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state <= 3'b001;
                end else if (r[0] == 1'b0 && r[1] == 1'b1 && r[2] == 1'b0) begin
                    next_state <= 3'b010;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
                    next_state <= 3'b011;
                end else begin
                    next_state <= 3'b000;
                end
            end
            3'b001: begin
                if (r[0] == 1'b1 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state <= 3'b001;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state <= 3'b000;
                end else begin
                    next_state <= 3'b001;
                end
            end
            3'b010: begin
                if (r[0] == 1'b0 && r[1] == 1'b1 && r[2] == 1'b0) begin
                    next_state <= 3'b010;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state <= 3'b000;
                end else begin
                    next_state <= 3'b010;
                end
            end
            3'b011: begin
                if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b1) begin
                    next_state <= 3'b011;
                end else if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
                    next_state <= 3'b000;
                end else begin
                    next_state <= 3'b011;
                end
            end
            default: begin
                next_state <= 3'b000;
            end
        endcase
    end
    always @(state) begin
        case (state)
            3'b000: begin
                g <= 3'b000;
            end
            3'b001: begin
                g <= 3'b001;
            end
            3'b010: begin
                g <= 3'b010;
            end
            3'b011: begin
                g <= 3'b011;
            end
            default: begin
                g <= 3'b000;
            end
        endcase
    end
endmodule

