module TopModule (
  input clk,
  input reset,
  input s,
  input w,
  output reg z
);
parameter A = 1'b0;
  parameter B = 1'b1;

  reg [1:0] state;
  always @(posedge clk) begin
    if (reset) begin
      state <= A;
    end else begin
      case (state)
        A: begin
          if (s == 1'b0) begin
            state <= A;
          end else begin
            state <= B;
          end
        end
        B: begin
          if (w == 1'b1) begin
            z <= 1'b1;
          end else begin
            z <= 1'b0;
          end
          state <= A;
        end
      endcase
    end
  end
endmodule

module TopModule (
