      3'b011: y_next = 3'b100;
      3'b100: y_next = 3'b101;
      3'b101: y_next = 3'b100;
      default: y_next = 3'b000;
    endcase
  end

  always @(*) begin
    case (y_next)
      3'b001: Y1 = 1'b0;
      3'b011: Y1 = 1'b0;
      3'b100: Y1 = 1'b0;
      3'b101: Y1 = 1'b1;
      default: Y1 = 1'b0;
    endcase
  end

  always @(posedge w) begin
    y <= y_next;
  end

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);
reg [3:0] state;
  reg [7:0] data;
  reg [1:0] bit_count;
  reg [1:0] stop_count;
  reg [1:0] stop_count_next;
  reg [1:0] bit_count_next;
  reg [1:0] state_next;
  reg done_next;
  always @(posedge clk) begin
    if (reset) begin
      state <= 0;
      data <= 0;
      bit_count <= 0;
      stop_count <= 0;
      done <= 0;
    end else begin
      state <= state_next;
      data <= data;
      bit_count <= bit_count_next;
      stop_count <= stop_count_next;
      done <= done_next;
    end
  end
  always @(*) begin
    state_next = state;
    data = data;
    bit_count_next = bit_count;
    stop_count_next = stop_count;
    done_next = done;
    case (state)
      0: begin
        if (in == 0) begin
          state_next = 1;
          bit_count_next = 0;
          stop_count_next = 0;
        end
      end
      1: begin
        if (in == 1) begin
          state_next = 2;
          bit_count_next = 0;
          stop_count_next = 0;
        end
      end
      2: begin
        if (bit_count == 7) begin
          state_next = 3;
          bit_count_next = 0;
          stop_count_next = 0;
        end else begin
          data[bit_count] = in;
          bit_count_next = bit_count + 1;
          stop_count_next = stop_count;
        end
      end
      3: begin
        if (in == 1) begin
          state_next = 4;
          bit_count_next = 0;
          stop_count_next = 0;
        end else begin
          state_next = 3;
          bit_count_next = bit_count;
          stop_count_next = stop_count + 1;
        end
      end
      4: begin
        if (stop_count == 1) begin
          state_next = 0;
          bit_count_next = 0;
          stop_count_next = 0;
          done_next = 1;
        end else begin
          state_next = 4;
          bit_count_next = 0;
          stop_count_next = stop_count + 1;
        end
      end
      default: begin
        state_next = 0;
        data = 0;
        bit_count_next = 0;
        stop_count_next = 0;
        done_next = 0;
      end
    endcase
  end
endmodule

